from math import pi
from qiskit import QuantumCircuit

qc = QuantumCircuit(5)

# Textbook QFT, with controlled-phase rotations and final bit-order reversal.
for target in range(4, -1, -1):
    qc.h(target)
    for control in range(target - 1, -1, -1):
        qc.cp(pi / (2 ** (target - control)), control, target)

for qubit in range(2):
    qc.swap(qubit, 4 - qubit)
